from pathlib import Path
import base64,html,shutil
root=Path(__file__).resolve().parent.parent;qa=root/'qa/focus-iterations';target=Path('/workspace/artifacts/Focus-improvement-review-20261025.html')
def pic(path,alt):
 return '<img loading="lazy" alt="'+html.escape(alt)+'" src="data:image/png;base64,'+base64.b64encode(path.read_bytes()).decode()+'">'
parts=['''<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Focus — 3周の改善比較</title><style>body{margin:0;background:#f4f6f5;color:#182d24;font:15px/1.7 system-ui,sans-serif}main{max-width:1100px;margin:auto;padding:24px}h1{font-size:27px}h2{font-size:21px;margin-top:36px}h3{font-size:16px}a{color:#176044}nav{display:flex;gap:18px;flex-wrap:wrap}table{border-collapse:collapse;width:100%;margin:20px 0}td,th{border-bottom:1px solid #cad7d0;padding:12px;text-align:left;vertical-align:top}.gallery{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}figure{margin:0;background:white;border:1px solid #cad7d0;border-radius:12px;padding:12px}img{display:block;width:100%;max-height:720px;object-fit:contain;object-position:top}figcaption{font-size:13px;margin-bottom:10px;color:#426052}.note{background:#e6eee9;padding:16px;border-radius:12px}details{background:white;padding:16px;border:1px solid #cad7d0;border-radius:12px;margin:12px 0}summary{cursor:pointer;font-weight:600}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:14px/1.8 system-ui,sans-serif}small{color:#426052}@media(max-width:700px){main{padding:16px}.gallery{grid-template-columns:1fr}td,th{padding:8px;font-size:13px}}</style><main><h1>Focus — 3周の改善比較</h1><p>2026-10-25 · 端末内テスト版 · 公開なし</p><nav><a href="#round1">1周目</a><a href="#round2">2周目</a><a href="#round3">3周目</a><a href="#templates">4テンプレート</a><a href="#checks">検証結果</a></nav><p class="note">通常のテストには3周目のZIPを使用します。各ZIPに起動ファイル・ソース・検証結果を残しました。画像はすべて検証用の架空データです。</p><table><tr><th>周</th><th>改善</th><th>確認結果</th></tr><tr><td>1</td><td>直接選択、編集取消、計測操作を上部へ</td><td>4画面幅、4テンプレート×PC/スマホ合格</td></tr><tr><td>2</td><td>表示/非表示、全幅、余白、明暗、表示件数</td><td>設定の永続化・段階表示合格。配色と件数初期化を修正</td></tr><tr><td>3</td><td>数値・復元検査、編集復帰、旧記録保持</td><td>12種類の不正復元、計測、競合、保存失敗の検証合格</td></tr></table><h2>計測中の操作位置</h2><p>同じ3ルーチンの集中テンプレート、390×844で比較。終了ボタン下端は約769pxから約259pxへ移動。開始→終了の操作はどちらも2クリックです。</p><div class="gallery"><figure><figcaption>変更前</figcaption>''',pic(qa/'baseline/mobile.png','変更前の計測画面'),'</figure><figure><figcaption>3周目</figcaption>',pic(qa/'round3/timer-mobile.png','改善後の計測画面'),'</figure></div><h2>入力の導線</h2><p>1〜6個のルーチンでは、切替→記録が3クリックから2クリックへ。昨日→記録は2クリック、同じ下書きの記録は1クリックのままです。内容・時刻・分数が適切な場合の操作数で、文字入力やホイール調整・スクロールは別です。人間の所要時間は測定していません。</p>']
for n in range(1,4):
 parts+= [f'<h2 id="round{n}">{n}周目</h2><div class="gallery"><figure><figcaption>スマホ幅390px</figcaption>',pic(qa/f'round{n}/390.png',f'{n}周目スマホ画面'),'</figure><figure><figcaption>PC幅1440px</figcaption>',pic(qa/f'round{n}/1440.png',f'{n}周目PC画面'),'</figure></div><details><summary>改善内容と実行結果</summary><pre>',html.escape((qa/f'round{n}/REPORT.md').read_text()),'</pre></details>']
parts+=['<h2>設定と明るいテーマ</h2><div class="gallery"><figure><figcaption>配置・表示の設定（3周目）</figcaption>',pic(qa/'round3/settings-mobile.png','配置とパネル表示の設定'),'</figure><figure><figcaption>ライト・コンパクト（3周目）</figcaption>',pic(qa/'round3/custom-390.png','明るいテーマとカレンダー'),'</figure></div><h2 id="templates">4テンプレート（最終版）</h2>']
for key,label in [('focus','集中'),('plan','予定'),('log','記録'),('progress','積み上げ')]:
 parts+=['<details><summary>'+label+'</summary><div class="gallery"><figure><figcaption>PC</figcaption>',pic(root/f'qa/focus/{key}-desktop.png',label+'PC'),'</figure><figure><figcaption>スマホ</figcaption>',pic(root/f'qa/focus/{key}-mobile.png',label+'スマホ'),'</figure></div></details>']
parts+=['<h2 id="checks">検証結果と範囲</h2><pre>',html.escape((root/'FOCUS-ITERATIONS.md').read_text()),'</pre></main></html>'];target.write_text(''.join(parts));shutil.copy2(target,root/'focus-test/改善比較.html');shutil.copy2(root/'FOCUS-ITERATIONS.md',root/'focus-test/FOCUS-ITERATIONS.md');print(target.name,target.stat().st_size)
